		8056, 8145, 8194, 8195, 8209, 8288, 8289, 8290, 8291, 8292, 9168, 9171, 9173, 9347,
		9471, 9493, 9848, 9858, 10078, 10079, 10171, 10172, 10173, 10501, 10601, 10602,
		10656, 10989, 10990, 11057, 11222, 11275, 11938, 12397, 13142, 13143, 13144, 13145
	};
	private static final int[] MAGIC_CAST_ANIMATIONS =
	{
		708, 811, 1162, 1166, 1167, 1576, 1978, 1979, 7855, 8972, 8977, 11423, 11430, 12397
	};
	private static final int[] NON_DAMAGE_MAGIC_CAST_ANIMATIONS =
	{
		1161, 1163, 1164, 1165, 1168, 1169, 8974
	};

	private AttackAnimationFilter()
	{
	}

	static boolean isAttack(int animationId)
	{
		return Arrays.binarySearch(ATTACK_ANIMATIONS, animationId) >= 0 || isMagicCast(animationId);
	}

	static boolean isMagicCast(int animationId)
	{
		return Arrays.binarySearch(MAGIC_CAST_ANIMATIONS, animationId) >= 0;
	}

	static boolean isNonDamageMagicCast(int animationId)
	{
		return Arrays.binarySearch(NON_DAMAGE_MAGIC_CAST_ANIMATIONS, animationId) >= 0;
	}
}

package com.webben.zeroxpdrops;

final class AttackAnimationStartDetector
{
	enum Start
	{
		NONE,
		NEW_ANIMATION,
		REPEATED_ANIMATION
	}

	private int previousAnimation = -1;
	private int previousFrame = -1;

	Start observe(int animation, int frame)
	{
		Start start = Start.NONE;
		if (animation != -1)
		{
			if (animation != previousAnimation)
			{
				start = Start.NEW_ANIMATION;
			}
			else if (frame == 0 && previousFrame > 0)
			{
				start = Start.REPEATED_ANIMATION;
			}
		}

		previousAnimation = animation;
		previousFrame = frame;
		return start;
	}

	void clear()
	{
		previousAnimation = -1;
		previousFrame = -1;
	}
}

package com.webben.zeroxpdrops;

import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.Deque;
import java.util.Iterator;
import java.util.List;

final class AttackMissTracker
{
	private static final int MAX_PENDING_ATTACKS = 8;
	private final Deque<PendingAttack> pending = new ArrayDeque<>();
	private int lastHitpointsXpTick = Integer.MIN_VALUE;

	boolean attackAnimation(MissType type, int currentTick, int currentCycle, int resolveCycle,
		Object target, boolean repeatedAnimation)
	{
		if (!isSupported(type) || target == null || wasRecentlyConfirmed(currentTick, repeatedAnimation))
		{
			return false;
		}

		PendingAttack existing = findDuplicate(type, currentTick, target);
		if (existing != null)
		{
			existing.resolveCycle = Math.max(existing.resolveCycle, resolveCycle);
			return false;
		}

		add(type, currentTick, currentCycle, resolveCycle, target);
		return true;
	}

	ResolvedAttack hitpointsXpReceived(int currentTick, int currentCycle)
	{
		lastHitpointsXpTick = currentTick;

		PendingAttack best = null;
		for (PendingAttack attack : pending)
		{
			if (attack.startedCycle <= currentCycle
				&& (best == null || attack.resolveCycle < best.resolveCycle))
			{
				best = attack;
			}
		}
		if (best == null)
		{
			return null;
		}

		pending.remove(best);
		return best.resolve();
	}

	List<ResolvedAttack> pollMisses(int currentCycle)
	{
		List<ResolvedAttack> misses = new ArrayList<>();
		Iterator<PendingAttack> iterator = pending.iterator();
		while (iterator.hasNext())
		{
			PendingAttack attack = iterator.next();
			if (currentCycle >= attack.resolveCycle)
			{
				misses.add(attack.resolve());
				iterator.remove();
			}
		}
		return misses;
	}

	void clear()
	{
		pending.clear();
		lastHitpointsXpTick = Integer.MIN_VALUE;
	}

	int size()
	{
		return pending.size();
	}

	private void add(MissType type, int currentTick, int currentCycle, int resolveCycle, Object target)
	{
		while (pending.size() >= MAX_PENDING_ATTACKS)
		{
			pending.removeFirst();
		}
		pending.addLast(new PendingAttack(type, currentTick, currentCycle,
			Math.max(currentCycle + 1, resolveCycle), target));
	}

	private PendingAttack findDuplicate(MissType type, int currentTick, Object target)
	{
		for (PendingAttack attack : pending)
		{
			if (attack.startedTick == currentTick && attack.target == target && attack.type == type)
			{
				return attack;
			}
		}
		return null;
	}

	private boolean wasRecentlyConfirmed(int currentTick, boolean repeatedAnimation)
	{
		long tickDifference = (long) currentTick - lastHitpointsXpTick;
		return tickDifference == 0 || repeatedAnimation && tickDifference == 1;
	}

	private static boolean isSupported(MissType type)
	{
		return type != null && type != MissType.UNSUPPORTED;
	}

	static final class ResolvedAttack
	{
		private final MissType type;
		private final Object target;

		private ResolvedAttack(MissType type, Object target)
		{
			this.type = type;
			this.target = target;
		}

		MissType getType()
		{
			return type;
		}

		Object getTarget()
		{
			return target;
		}
	}

	private static final class PendingAttack
	{
		private final MissType type;
		private final int startedTick;
		private final int startedCycle;
		private int resolveCycle;
		private final Object target;

		private PendingAttack(MissType type, int startedTick, int startedCycle, int resolveCycle, Object target)
		{
			this.type = type;
			this.startedTick = startedTick;
			this.startedCycle = startedCycle;
			this.resolveCycle = resolveCycle;
			this.target = target;
		}

		private ResolvedAttack resolve()
		{
			return new ResolvedAttack(type, target);
		}
	}
}

package com.webben.zeroxpdrops;

import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.EquipmentInventorySlot;
import net.runelite.api.Item;
import net.runelite.api.ItemContainer;
import net.runelite.api.gameval.InventoryID;
import net.runelite.client.game.ItemEquipmentStats;
import net.runelite.client.game.ItemManager;
import net.runelite.client.game.ItemStats;

final class CombatStyleDetector
{
	private final Client client;
	private final ItemManager itemManager;

	@Inject
	CombatStyleDetector(Client client, ItemManager itemManager)
	{
		this.client = client;
		this.itemManager = itemManager;
	}

	MissType currentType()
	{
		ItemContainer worn = client.getItemContainer(InventoryID.WORN);
		if (worn == null)
		{
			return MissType.MELEE;
		}
		Item weapon = worn.getItem(EquipmentInventorySlot.WEAPON.getSlotIdx());
		if (weapon == null)
		{
			return MissType.MELEE;
		}
		ItemStats itemStats = itemManager.getItemStats(weapon.getId());
		return itemStats == null ? MissType.MELEE : fromEquipment(itemStats.getEquipment());
	}

	static MissType fromEquipment(ItemEquipmentStats equipment)
	{
		if (equipment == null)
		{
			return MissType.MELEE;
		}
		int meleeAccuracy = Math.max(equipment.getAstab(), Math.max(equipment.getAslash(), equipment.getAcrush()));
		if (equipment.getArange() > meleeAccuracy && equipment.getArange() >= equipment.getAmagic())
		{
			return MissType.RANGED;
		}
		if (equipment.getAmagic() > meleeAccuracy && equipment.getAmagic() > equipment.getArange())
		{
			return MissType.MAGIC;
		}
		return MissType.MELEE;
	}
}

