package com.webben.zeroxpdrops;

import net.runelite.api.Skill;

enum MissType
{
	MELEE,
	RANGED,
	MAGIC,
	UNSUPPORTED;

	static MissType fromSkill(Skill skill)
	{
		if (skill == Skill.RANGED)
		{
			return RANGED;
		}
		if (skill == Skill.MAGIC)
		{
			return MAGIC;
		}
		if (skill == Skill.ATTACK || skill == Skill.STRENGTH || skill == Skill.DEFENCE)
		{
			return MELEE;
		}
		return UNSUPPORTED;
	}
}

package com.webben.zeroxpdrops;

import java.awt.Color;
import net.runelite.api.Client;
import net.runelite.api.Prayer;

final class PrayerColorResolver
{
	private static final Prayer[] MELEE_PRAYERS =
	{
		Prayer.BURST_OF_STRENGTH, Prayer.CLARITY_OF_THOUGHT,
		Prayer.SUPERHUMAN_STRENGTH, Prayer.IMPROVED_REFLEXES,
		Prayer.ULTIMATE_STRENGTH, Prayer.INCREDIBLE_REFLEXES,
		Prayer.CHIVALRY, Prayer.PIETY, Prayer.RP_ANCIENT_STRENGTH, Prayer.RP_DECIMATE
	};
	private static final Prayer[] RANGED_PRAYERS =
	{
		Prayer.SHARP_EYE, Prayer.HAWK_EYE, Prayer.EAGLE_EYE, Prayer.DEADEYE,
		Prayer.RIGOUR, Prayer.RP_ANCIENT_SIGHT, Prayer.RP_ANNIHILATE
	};
	private static final Prayer[] MAGIC_PRAYERS =
	{
		Prayer.MYSTIC_WILL, Prayer.MYSTIC_LORE, Prayer.MYSTIC_MIGHT, Prayer.MYSTIC_VIGOUR,
		Prayer.AUGURY, Prayer.RP_ANCIENT_WILL, Prayer.RP_VAPORISE
	};
	private static final Prayer[] ALL_STYLE_PRAYERS =
	{
		Prayer.RP_TRINITAS, Prayer.RP_INTENSIFY
	};

	private PrayerColorResolver()
	{
	}

	static Color resolve(Client client, ZeroXpDropsConfig config, MissType type)
	{
		if (type == null || type == MissType.UNSUPPORTED)
		{
			return config.textColor();
		}

		Prayer[] stylePrayers = prayersFor(type);
		if (!hasActive(client, stylePrayers) && !hasActive(client, ALL_STYLE_PRAYERS))
		{
			return config.textColor();
		}

		switch (type)
		{
			case MELEE:
				return config.meleePrayerColor();
			case RANGED:
				return config.rangedPrayerColor();
			case MAGIC:
				return config.magicPrayerColor();
			default:
				return config.textColor();
		}
	}

	static boolean supports(Prayer prayer, MissType type)
	{
		return contains(prayersFor(type), prayer) || contains(ALL_STYLE_PRAYERS, prayer);
	}

	private static Prayer[] prayersFor(MissType type)
	{
		if (type == null)
		{
			return new Prayer[0];
		}
		switch (type)
		{
			case MELEE:
				return MELEE_PRAYERS;
			case RANGED:
				return RANGED_PRAYERS;
			case MAGIC:
				return MAGIC_PRAYERS;
			default:
				return new Prayer[0];
		}
	}

	private static boolean hasActive(Client client, Prayer[] prayers)
	{
		for (Prayer prayer : prayers)
		{
			if (client.isPrayerActive(prayer))
			{
				return true;
			}
		}
		return false;
	}

	private static boolean contains(Prayer[] prayers, Prayer sought)
	{
		for (Prayer prayer : prayers)
		{
			if (prayer == sought)
			{
				return true;
			}
		}
		return false;
	}
}

package com.webben.zeroxpdrops;

import java.awt.AlphaComposite;
import java.awt.Color;
import java.awt.Composite;
import java.awt.Dimension;
import java.awt.Font;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.awt.image.BufferedImage;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.SpriteID;
import net.runelite.api.SpritePixels;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;

final class ZeroXpDropOverlay extends Overlay
{
	private static final int PADDING = 8;
	private static final int ICON_GAP = 2;
	private static final Color SHADOW = new Color(0, 0, 0, 220);
	private final Client client;
	private final ZeroXpDropsPlugin plugin;
	private final ZeroXpDropsConfig config;
	private BufferedImage hitmarkIcon;
	private boolean iconLoadAttempted;

	@Inject
	ZeroXpDropOverlay(Client client, ZeroXpDropsPlugin plugin, ZeroXpDropsConfig config)
	{
		this.client = client;
		this.plugin = plugin;
		this.config = config;
		setPosition(OverlayPosition.TOP_CENTER);
		setLayer(OverlayLayer.UNDER_WIDGETS);
		setPriority(Overlay.PRIORITY_HIGH);
		setMovable(true);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		if (isAttached() || plugin.visibleMillisRemaining() <= 0)
		{
			return null;
		}

		Layout layout = layout(graphics);
		double elapsed = plugin.animationElapsedSeconds();
		int totalY = (int) Math.round(config.yPixelsPerSecond() * config.framesPerDrop() / 50.0);
		int movedY = (int) Math.round(config.yPixelsPerSecond() * elapsed);
		int top = PADDING + (config.fadeDirection() == FadeDirection.UP ? totalY - movedY : movedY);
		int x = PADDING - layout.minX;
		int baselineY = top - layout.minY;
		draw(graphics, layout, x, baselineY, alpha());
		return new Dimension(layout.width + PADDING * 2, layout.height + totalY + PADDING * 2);
	}

	void drawCentered(Graphics2D graphics, int centerX, int baselineY)
	{
		Layout layout = layout(graphics);
		int centeredX = centerX - (layout.minX + layout.maxX) / 2;
		draw(graphics, layout, centeredX, baselineY, alpha());
	}

	private Layout layout(Graphics2D graphics)
	{
		Font font = FontManager.getRunescapeBoldFont().deriveFont((float) config.fontSize());
		graphics.setRenderingHint(RenderingHints.KEY_TEXT_ANTIALIASING, RenderingHints.VALUE_TEXT_ANTIALIAS_ON);
		graphics.setRenderingHint(RenderingHints.KEY_INTERPOLATION, RenderingHints.VALUE_INTERPOLATION_BICUBIC);
		graphics.setFont(font);
		FontMetrics metrics = graphics.getFontMetrics();
		BufferedImage icon = config.showHitmarkIcon() ? getHitmarkIcon() : null;
		int iconSize = icon == null ? 0 : config.hitmarkIconSize();
		int textWidth = metrics.stringWidth(config.displayMode().getText());
		boolean iconBehind = icon != null && config.hitsplatBehindDrop()
			&& config.displayMode() == MissDisplayMode.ZERO;
		int naturalWidth = iconBehind ? Math.max(textWidth, iconSize)
			: textWidth + (iconSize == 0 ? 0 : iconSize + ICON_GAP);
		int textX = (iconBehind ? (naturalWidth - textWidth) / 2
			: (iconSize == 0 ? 0 : iconSize + ICON_GAP)) + config.textOffsetX();
		int textBaselineOffset = config.textOffsetY();
		int iconX = iconBehind ? (naturalWidth - iconSize) / 2 : 0;
		int iconTop = -metrics.getAscent() + (metrics.getHeight() - iconSize) / 2;
		if (icon != null)
		{
			iconX += config.hitmarkOffsetX();
			iconTop += config.hitmarkOffsetY();
		}

		int minX = textX;
		int maxX = textX + textWidth;
		int minY = textBaselineOffset - metrics.getAscent();
		int maxY = textBaselineOffset + metrics.getDescent();
		if (icon != null)
		{
			minX = Math.min(minX, iconX);
			maxX = Math.max(maxX, iconX + iconSize);
			minY = Math.min(minY, iconTop);
			maxY = Math.max(maxY, iconTop + iconSize);
		}
		return new Layout(metrics, icon, iconSize, Math.max(1, maxX - minX),
			Math.max(1, maxY - minY), iconBehind, textX, textBaselineOffset,
			iconX, iconTop, minX, maxX, minY);
	}

	private void draw(Graphics2D graphics, Layout layout, int x, int baselineY, float alpha)
	{
		String text = config.displayMode().getText();
		int textX = x + layout.textX;
		int textBaselineY = baselineY + layout.textBaselineOffset;
		if (layout.icon != null)
		{
			Composite original = graphics.getComposite();
			graphics.setComposite(AlphaComposite.getInstance(AlphaComposite.SRC_OVER, alpha));
			graphics.drawImage(layout.icon, x + layout.iconX, baselineY + layout.iconTop,
				layout.iconSize, layout.iconSize, null);
			graphics.setComposite(original);
		}

		Color configured = PrayerColorResolver.resolve(client, config, plugin.activeMissType());
		graphics.setColor(withAlpha(SHADOW, alpha));
		graphics.drawString(text, textX + 2, textBaselineY + 2);
		graphics.setColor(withAlpha(configured, alpha));
		graphics.drawString(text, textX, textBaselineY);
	}

	private float alpha()
	{
		if (!config.fadeOut())
		{
			return 1f;
		}
		double progress = plugin.animationProgress();
		double fadeStart = 0.66;
		return progress <= fadeStart ? 1f
			: (float) Math.max(0.0, Math.min(1.0, (1.0 - progress) / (1.0 - fadeStart)));
	}

	private boolean isAttached()
	{
		return config.attachToPlayer() || config.attachToTarget();
	}

	private BufferedImage getHitmarkIcon()
	{
		if (!iconLoadAttempted)
		{
			iconLoadAttempted = true;
			SpritePixels[] sprites = client.getSprites(client.getIndexSprites(), SpriteID.HITSPLAT_BLUE_MISS, 0);
			if (sprites != null && sprites.length > 0 && sprites[0] != null)
			{
				hitmarkIcon = sprites[0].toBufferedImage();
			}
		}
		return hitmarkIcon;
	}

	private static Color withAlpha(Color color, float alpha)
	{
		return new Color(color.getRed(), color.getGreen(), color.getBlue(),
			Math.max(0, Math.min(255, Math.round(color.getAlpha() * alpha))));
	}

	private static final class Layout
	{
		private final FontMetrics metrics;
		private final BufferedImage icon;
		private final int iconSize;
		private final int width;
		private final int height;
		private final boolean iconBehind;
		private final int textX;
		private final int textBaselineOffset;
		private final int iconX;
		private final int iconTop;
		private final int minX;
		private final int maxX;
		private final int minY;

		private Layout(FontMetrics metrics, BufferedImage icon, int iconSize, int width, int height,
			boolean iconBehind, int textX, int textBaselineOffset, int iconX, int iconTop,
			int minX, int maxX, int minY)
		{
			this.metrics = metrics;
			this.icon = icon;
			this.iconSize = iconSize;
			this.width = width;
			this.height = height;
			this.iconBehind = iconBehind;
			this.textX = textX;
			this.textBaselineOffset = textBaselineOffset;
			this.iconX = iconX;
			this.iconTop = iconTop;
			this.minX = minX;
			this.maxX = maxX;
			this.minY = minY;
		}
	}
}

package com.webben.zeroxpdrops;

import java.awt.Dimension;
import java.awt.Graphics2D;
import javax.inject.Inject;
import net.runelite.api.Actor;
import net.runelite.api.Client;
import net.runelite.api.Point;
import net.runelite.api.Player;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;

final class ZeroXpDropSceneOverlay extends Overlay
{
	private final Client client;
	private final ZeroXpDropsPlugin plugin;
	private final ZeroXpDropsConfig config;
	private final ZeroXpDropOverlay renderer;

	@Inject
	ZeroXpDropSceneOverlay(Client client, ZeroXpDropsPlugin plugin, ZeroXpDropsConfig config,
		ZeroXpDropOverlay renderer)
	{
		this.client = client;
		this.plugin = plugin;
		this.config = config;
		this.renderer = renderer;
		setLayer(OverlayLayer.UNDER_WIDGETS);
		setPosition(OverlayPosition.DYNAMIC);
		setPriority(Overlay.PRIORITY_HIGH);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		if ((!config.attachToPlayer() && !config.attachToTarget()) || plugin.visibleMillisRemaining() <= 0)
		{
			return null;
		}

		Player player = client.getLocalPlayer();
		Actor actor = config.attachToTarget() ? plugin.activeTarget() : null;
		if (actor == null && config.attachToPlayer())
		{
			actor = player;
		}
		if (actor == null)
		{
			return null;
		}

		Point point = actor.getCanvasTextLocation(graphics, "x", Math.min(actor.getLogicalHeight(), 140));
		if (point == null)
		{
			return null;
		}

		double elapsed = plugin.animationElapsedSeconds();
		int movementY = (int) Math.round(config.yPixelsPerSecond() * elapsed)
			* (config.fadeDirection() == FadeDirection.UP ? -1 : 1);
		int x = point.getX() + config.attachToOffsetX();
		int y = point.getY() - config.attachToOffsetY() + movementY;
		renderer.drawCentered(graphics, x, y);
		return null;
	}
}

package com.webben.zeroxpdrops;

