package com.webben.zeroxpdrops;

import com.google.inject.Provides;
import javax.inject.Inject;
import net.runelite.api.Actor;
import net.runelite.api.Client;
import net.runelite.api.NPC;
import net.runelite.api.Player;
import net.runelite.api.Skill;
import net.runelite.api.events.AnimationChanged;
import net.runelite.api.events.ClientTick;
import net.runelite.api.events.FakeXpDrop;
import net.runelite.api.events.StatChanged;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.overlay.OverlayManager;

@PluginDescriptor(
	name = "Zero XP Drops",
	description = "Shows MISS or 0 when an attack produces no qualifying Hitpoints XP",
	tags = {"xp", "experience", "miss", "combat", "melee", "ranged", "magic", "overlay"}
)
public class ZeroXpDropsPlugin extends Plugin
{
	private static final int XP_EVENT_GRACE_CYCLES = 4;

	@Inject
	private Client client;

	@Inject
	private ZeroXpDropsConfig config;

	@Inject
	private OverlayManager overlayManager;

	@Inject
	private ZeroXpDropOverlay overlay;

	@Inject
	private ZeroXpDropSceneOverlay sceneOverlay;

	@Inject
	private CombatStyleDetector combatStyleDetector;

	private volatile long visibleUntilNanos;
	private volatile long shownAtNanos;
	private volatile int activeDurationMillis;
	private int lastMissTick = Integer.MIN_VALUE;
	private Actor activeTarget;
	private MissType activeMissType = MissType.UNSUPPORTED;
	private final AttackMissTracker attackMissTracker = new AttackMissTracker();
	private int lastHitpointsXp;
	private final AttackAnimationStartDetector animationStartDetector = new AttackAnimationStartDetector();

	@Provides
	ZeroXpDropsConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(ZeroXpDropsConfig.class);
	}

	@Override
	protected void startUp()
	{
		overlayManager.add(overlay);
		overlayManager.add(sceneOverlay);
		lastHitpointsXp = client.getSkillExperience(Skill.HITPOINTS);
	}

	@Override
	protected void shutDown()
	{
		overlayManager.remove(overlay);
		overlayManager.remove(sceneOverlay);
		visibleUntilNanos = 0L;
		lastMissTick = Integer.MIN_VALUE;
		attackMissTracker.clear();
		activeTarget = null;
		activeMissType = MissType.UNSUPPORTED;
		lastHitpointsXp = 0;
		animationStartDetector.clear();
	}

	@Subscribe
	public void onAnimationChanged(AnimationChanged event)
	{
		Player localPlayer = client.getLocalPlayer();
		if (localPlayer == null || event.getActor() != localPlayer)
		{
			return;
		}
		observeAttackAnimation(localPlayer);
	}

	private void observeAttackAnimation(Player localPlayer)
	{
		int animation = localPlayer.getAnimation();
		int animationFrame = localPlayer.getAnimationFrame();
		AttackAnimationStartDetector.Start start = animationStartDetector.observe(animation, animationFrame);
		boolean repeatedAnimation = start == AttackAnimationStartDetector.Start.REPEATED_ANIMATION;

		if (AttackAnimationFilter.isNonDamageMagicCast(animation))
		{
			return;
		}
		if (start == AttackAnimationStartDetector.Start.NONE || !(localPlayer.getInteracting() instanceof NPC)
			|| !AttackAnimationFilter.isAttack(animation) || DefensiveAnimationFilter.isDefensive(animation))
		{
			return;
		}

		MissType type = AttackAnimationFilter.isMagicCast(animation)
			? MissType.MAGIC : combatStyleDetector.currentType();
		if (isEnabled(type))
		{
			int currentCycle = client.getGameCycle();
			attackMissTracker.attackAnimation(type, client.getTickCount(), currentCycle,
				currentCycle + XP_EVENT_GRACE_CYCLES, localPlayer.getInteracting(), repeatedAnimation);
		}
	}

	@Subscribe
	public void onStatChanged(StatChanged event)
	{
		if (event.getSkill() == Skill.HITPOINTS)
		{
			int gained = event.getXp() - lastHitpointsXp;
			lastHitpointsXp = event.getXp();
			if (gained >= Math.max(1, config.minimumValidXpDrop()))
			{
				attackMissTracker.hitpointsXpReceived(client.getTickCount(), client.getGameCycle());
			}
		}
	}

	@Subscribe
	public void onFakeXpDrop(FakeXpDrop event)
	{
		// RuneLite emits this when the game displays XP without changing the stored
		// total, such as capped Hitpoints XP or targets with blocked XP rewards.
		// Only Hitpoints confirms damage; Magic XP alone can also be a splash.
		if (event.getSkill() == Skill.HITPOINTS
			&& event.getXp() >= Math.max(1, config.minimumValidXpDrop()))
		{
			attackMissTracker.hitpointsXpReceived(client.getTickCount(), client.getGameCycle());
		}
	}

	@Subscribe
	public void onClientTick(ClientTick event)
	{
		Player localPlayer = client.getLocalPlayer();
		if (localPlayer != null)
		{
			observeAttackAnimation(localPlayer);
		}

		int currentCycle = client.getGameCycle();
		for (AttackMissTracker.ResolvedAttack missed : attackMissTracker.pollMisses(currentCycle))
		{
			if (isEnabled(missed.getType()))
			{
				triggerMiss((Actor) missed.getTarget(), missed.getType());
			}
		}
	}

	private void triggerMiss(Actor target, MissType type)
	{
		int tick = client.getTickCount();
		if (tick != lastMissTick)
		{
			lastMissTick = tick;
			activeTarget = target;
			activeMissType = type;
			showOverlay(config.framesPerDrop() * 20);
		}
	}

	private boolean isEnabled(MissType type)
	{
		return type == MissType.MELEE && config.showMelee()
			|| type == MissType.RANGED && config.showRanged()
			|| type == MissType.MAGIC && config.showMagic();
	}

	void showOverlay(int durationMillis)
	{
		long now = System.nanoTime();
		shownAtNanos = now;
		activeDurationMillis = Math.max(1, durationMillis);
		visibleUntilNanos = now + activeDurationMillis * 1_000_000L;
	}

	long visibleMillisRemaining()
	{
		if (config.previewOverlay())
		{
			return Long.MAX_VALUE;
		}
		return Math.max(0L, (visibleUntilNanos - System.nanoTime()) / 1_000_000L);
	}

	double animationProgress()
	{
		if (config.previewOverlay())
		{
			return 0.0;
		}
		long elapsedNanos = Math.max(0L, System.nanoTime() - shownAtNanos);
		return Math.max(0.0, Math.min(1.0, elapsedNanos / (activeDurationMillis * 1_000_000.0)));
	}

	double animationElapsedSeconds()
	{
		return animationProgress() * activeDurationMillis / 1000.0;
	}

	Actor activeTarget()
	{
		return activeTarget;
	}

	MissType activeMissType()
	{
		return activeMissType;
	}

}

package com.webben.zeroxpdrops;

import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

import org.junit.Test;

public class AttackAnimationFilterTest
{
	@Test
	public void recognisesCommonCombatAnimations()
	{
		assertTrue(AttackAnimationFilter.isAttack(422));
		assertTrue(AttackAnimationFilter.isAttack(5061));
		assertTrue(AttackAnimationFilter.isAttack(1167));
		assertTrue(AttackAnimationFilter.isAttack(12397));
		assertTrue(AttackAnimationFilter.isAttack(1162));
		assertTrue(AttackAnimationFilter.isAttack(1979));
		assertTrue(AttackAnimationFilter.isAttack(11430));
		assertTrue(AttackAnimationFilter.isAttack(11938));
		assertTrue(AttackAnimationFilter.isAttack(13144));
		assertTrue(AttackAnimationFilter.isAttack(13145));
		assertTrue(AttackAnimationFilter.isMagicCast(1162));
		assertTrue(AttackAnimationFilter.isMagicCast(1979));
		assertTrue(AttackAnimationFilter.isNonDamageMagicCast(1161));
		assertTrue(AttackAnimationFilter.isNonDamageMagicCast(1165));
