		assertFalse(AttackAnimationFilter.isAttack(808));
		assertFalse(AttackAnimationFilter.isAttack(424));
		assertFalse(AttackAnimationFilter.isAttack(712));
		assertFalse(AttackAnimationFilter.isAttack(713));
		assertFalse(AttackAnimationFilter.isMagicCast(5061));
		assertFalse(AttackAnimationFilter.isAttack(1161));
		assertFalse(AttackAnimationFilter.isAttack(1165));
	}
}

package com.webben.zeroxpdrops;

import static org.junit.Assert.assertEquals;

import org.junit.Test;

public class AttackAnimationStartDetectorTest
{
	@Test
	public void detectsNewAnimationOnce()
	{
		AttackAnimationStartDetector detector = new AttackAnimationStartDetector();
		assertEquals(AttackAnimationStartDetector.Start.NEW_ANIMATION, detector.observe(5061, 0));
		assertEquals(AttackAnimationStartDetector.Start.NONE, detector.observe(5061, 0));
		assertEquals(AttackAnimationStartDetector.Start.NONE, detector.observe(5061, 1));
	}

	@Test
	public void detectsSameAnimationOnlyWhenItRestartsAtFrameZero()
	{
		AttackAnimationStartDetector detector = new AttackAnimationStartDetector();
		detector.observe(5061, 0);
		detector.observe(5061, 1);
		detector.observe(5061, 3);

		assertEquals(AttackAnimationStartDetector.Start.REPEATED_ANIMATION, detector.observe(5061, 0));
		assertEquals(AttackAnimationStartDetector.Start.NONE, detector.observe(5061, 0));
	}

	@Test
	public void ignoresInternalFrameRewindsAndAnimationEnd()
	{
		AttackAnimationStartDetector detector = new AttackAnimationStartDetector();
		detector.observe(12397, 0);
		detector.observe(12397, 5);

		assertEquals(AttackAnimationStartDetector.Start.NONE, detector.observe(12397, 2));
		assertEquals(AttackAnimationStartDetector.Start.NONE, detector.observe(-1, 0));
	}
}

package com.webben.zeroxpdrops;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

import java.util.List;
import org.junit.Test;

public class AttackMissTrackerTest
{
	@Test
	public void reportsMissAfterResolutionWindow()
	{
		AttackMissTracker tracker = new AttackMissTracker();
		Object target = new Object();
		tracker.attackAnimation(MissType.MELEE, 10, 100, 104, target, false);

		assertTrue(tracker.pollMisses(103).isEmpty());
		List<AttackMissTracker.ResolvedAttack> misses = tracker.pollMisses(104);
		assertEquals(1, misses.size());
		assertEquals(MissType.MELEE, misses.get(0).getType());
		assertEquals(target, misses.get(0).getTarget());
	}

	@Test
	public void hitpointsXpCancelsAttack()
	{
		AttackMissTracker tracker = new AttackMissTracker();
		tracker.attackAnimation(MissType.MELEE, 10, 100, 104, new Object(), false);

		tracker.hitpointsXpReceived(10, 102);
		assertTrue(tracker.pollMisses(104).isEmpty());
		assertEquals(0, tracker.size());
	}

	@Test
	public void blockedHitpointsXpDropCancelsAttack()
	{
		AttackMissTracker tracker = new AttackMissTracker();
		tracker.attackAnimation(MissType.MAGIC, 20, 200, 204, new Object(), false);

		// FakeXpDrop is routed through the same successful Hitpoints-XP path.
		tracker.hitpointsXpReceived(20, 202);
		assertTrue(tracker.pollMisses(204).isEmpty());
		assertEquals(0, tracker.size());
	}

	@Test
	public void fastConsecutiveAttacksRemainSeparate()
	{
		AttackMissTracker tracker = new AttackMissTracker();
		Object target = new Object();
		tracker.attackAnimation(MissType.RANGED, 50, 500, 504, target, false);
		tracker.attackAnimation(MissType.RANGED, 52, 560, 564, target, true);

		tracker.hitpointsXpReceived(50, 502);
		assertEquals(1, tracker.size());
		assertEquals(1, tracker.pollMisses(564).size());
	}

	@Test
	public void xpBeforeAnimationDoesNotCreatePhantomMiss()
	{
		AttackMissTracker tracker = new AttackMissTracker();
		Object target = new Object();
		tracker.hitpointsXpReceived(60, 600);

		assertFalse(tracker.attackAnimation(MissType.MAGIC, 60, 620, 624, target, false));
		assertEquals(0, tracker.size());
	}

	@Test
	public void hpXpProtectsEntireServerTick()
	{
		AttackMissTracker tracker = new AttackMissTracker();
		Object target = new Object();
		tracker.hitpointsXpReceived(70, 700);

		assertFalse(tracker.attackAnimation(MissType.RANGED, 70, 730, 734, target, false));
		assertEquals(0, tracker.size());
	}

	@Test
	public void previousTickXpProtectsRepeatedAnimation()
	{
		AttackMissTracker tracker = new AttackMissTracker();
		Object target = new Object();
		tracker.hitpointsXpReceived(80, 800);

		assertFalse(tracker.attackAnimation(MissType.RANGED, 81, 830, 834, target, true));
		assertEquals(0, tracker.size());
	}

	@Test
	public void previousTickXpDoesNotHideOrdinaryAnimation()
	{
		AttackMissTracker tracker = new AttackMissTracker();
		Object target = new Object();
		tracker.hitpointsXpReceived(90, 900);

		assertTrue(tracker.attackAnimation(MissType.MELEE, 91, 930, 934, target, false));
		assertEquals(1, tracker.size());
	}

	@Test
	public void olderXpDoesNotHideRapidWeaponMiss()
	{
		AttackMissTracker tracker = new AttackMissTracker();
		Object target = new Object();
		tracker.hitpointsXpReceived(100, 1000);

		assertTrue(tracker.attackAnimation(MissType.RANGED, 102, 1060, 1064, target, true));
		assertEquals(1, tracker.size());
	}
}

