package com.webben.zeroxpdrops;

import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

import net.runelite.api.Prayer;
import org.junit.Test;

public class PrayerColorResolverTest
{
	@Test
	public void mapsOffensivePrayersToTheirCombatStyle()
	{
		assertTrue(PrayerColorResolver.supports(Prayer.PIETY, MissType.MELEE));
		assertTrue(PrayerColorResolver.supports(Prayer.RIGOUR, MissType.RANGED));
		assertTrue(PrayerColorResolver.supports(Prayer.AUGURY, MissType.MAGIC));
		assertFalse(PrayerColorResolver.supports(Prayer.PIETY, MissType.RANGED));
	}

	@Test
	public void allStylePrayersSupportEveryCombatStyle()
	{
		assertTrue(PrayerColorResolver.supports(Prayer.RP_TRINITAS, MissType.MELEE));
		assertTrue(PrayerColorResolver.supports(Prayer.RP_TRINITAS, MissType.RANGED));
		assertTrue(PrayerColorResolver.supports(Prayer.RP_INTENSIFY, MissType.MAGIC));
	}
}

